While this program runs (the button is not pressed), these events happen: the button is held down between 100 and 200 ms, then held down again between 550 and 700 ms. What appears in the Serial monitor at the end of 2 seconds?

```
int sayac = 0;

void setup() {
  pinMode(13, OUTPUT);
  pinMode(2, INPUT_PULLUP);
  Serial.begin(9600);
}

void loop() {
  digitalWrite(13, HIGH);
  delay(300);
  digitalWrite(13, LOW);
  delay(300);
  if (digitalRead(2) == LOW) {
    sayac++;
    Serial.print("Basis sayisi: ");
    Serial.println(sayac);
  }
}
```

